// @comment-ok: the built program's usage contract, the one doc site for its verbs.
// GENERATED by `dl6 build` from v6/sprefa-engine-rs/src/build_template/main.rs.
//
// @comment-ok: the verb table.
//   <prog> run   [<schedule.json>] [--arrive <rel>=<v>[,<v>]]... [--final-tsv]
//                [--final] [--final-only] [--final-rels a,b] [--db <file>]
//                [--fail-on <query>] [--root <dir>] [--adapters-dir <dir>]
//   <prog> watch [same flags as run]
//   <prog> serve --socket <path> [--adapters-dir <dir>]
//   <prog> --version
//
// @comment-ok: `run`'s contract, continued.
// `run` prints the tick log on stdout and nothing else, byte for byte what
// emit_rust_harness prints for the same program and schedule, under the flags
// `dl6 run` takes.
//
// @comment-ok: `watch` and `serve`'s contract, continued.
// `watch` folds and then stays up on the program's own `bind` sources. `serve`
// holds the program resident behind serve.rs's routes on a socket file until
// SIGINT. The `.adapters.json` sidecar is embedded at build; `--adapters-dir`
// points the engine at a directory instead.

use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use anyhow::{Context, Result};
use clap::{Args, Parser, Subcommand};
use sprefa_engine_rs::program::{GenProgram, IR_VERSION};
use sprefa_engine_rs::run::{
    self, FinalRequest, RunOptions, SeedSpec, WatchOptions, DRAIN_CAP,
};
use sprefa_engine_rs::serve::{arrival_batch, serve_unix, ArrivalDto, ServeState};
use sprefa_engine_rs::sql::SqliteSeam;
use sprefa_engine_rs::types::Arrival;
use tokio_util::sync::CancellationToken;

mod emitted_program {
    include!("program.rs");
}

// The typed row surface the program's rels decode to. Nothing in these verbs
// reads it; it ships so a consumer of this crate can.
#[allow(dead_code)]
mod emitted_types {
    include!("types.rs");
}

const PROGRAM_NAME: &str = "__DL6_PROGRAM_NAME__";
const COMPILER_SHA: &str = "__DL6_COMPILER_SHA__";
const ADAPTERS_JSON: &str = include_str!("adapters.json");

// clap's `version` wants a &'static str, and IR_VERSION is only readable at
// run time, so the line is a static rather than a `concat!`.
static VERSION_LINE: LazyLock<String> =
    LazyLock::new(|| format!("compiler {COMPILER_SHA} ir_version {IR_VERSION}"));

#[derive(Parser)]
#[command(name = PROGRAM_NAME, version = VERSION_LINE.as_str(), about = "one dl6 program, one binary")]
struct Cli {
    #[command(subcommand)]
    verb: Verb,
}

#[derive(Subcommand)]
enum Verb {
    /// Fold once and print the tick log and the `?` rows.
    Run(ProgramArgs),
    /// Fold, then stay up on the program's own `bind` sources.
    Watch(ProgramArgs),
    /// Boot the program and answer its rels on a socket file until SIGINT.
    Serve {
        /// The socket file the program answers its rels on.
        #[arg(long, value_name = "PATH")]
        socket: PathBuf,
        /// Read `<prog>.adapters.json` from here instead of the embedded copy.
        #[arg(long, value_name = "DIR")]
        adapters_dir: Option<PathBuf>,
    },
}

/// The same option table `dl6 run` carries, so a program built
/// into a binary is driven with the flags it was driven with unbuilt.
#[derive(Args)]
struct ProgramArgs {
    /// An arrival schedule to fold before the seeds.
    schedule: Option<PathBuf>,
    /// Seed one arrival row. Repeat it for more.
    #[arg(long = "arrive", value_name = "REL=VALUE[,VALUE...]")]
    arrive: Vec<SeedSpec>,
    /// Print every `?` rel as one json document per rel.
    #[arg(long = "final")]
    final_all: bool,
    /// Print the `?` rows and drop the tick log.
    #[arg(long)]
    final_only: bool,
    /// Print the `?` rows as `rel<TAB>col...`.
    #[arg(long)]
    final_tsv: bool,
    /// Name and order the rels to print.
    #[arg(long, value_name = "REL[,REL...]", value_delimiter = ',')]
    final_rels: Option<Vec<String>>,
    /// Fold into a plain SQLite file a cold `sqlite3` reads afterwards.
    #[arg(long, value_name = "FILE")]
    db: Option<PathBuf>,
    /// Exit 1 when this `?` query answers any row.
    #[arg(long, value_name = "QUERY")]
    fail_on: Option<String>,
    /// The tree the hosts read and a `bind watch` glob is resolved against.
    #[arg(long, value_name = "DIR", default_value = ".")]
    root: PathBuf,
    /// Read `<prog>.adapters.json` from here instead of the embedded copy.
    #[arg(long, value_name = "DIR")]
    adapters_dir: Option<PathBuf>,
    /// Fold `sh` decls from a scripted schedule instead of running them live.
    #[arg(long)]
    no_live_hosts: bool,
}

impl ProgramArgs {
    fn finals(&self) -> FinalRequest {
        FinalRequest {
            wanted: self.final_all || self.final_only || self.final_tsv || self.final_rels.is_some(),
            only: self.final_only,
            tsv: self.final_tsv,
            rels: self.final_rels.clone(),
        }
    }
}

// With no override the embedded sidecar is materialized into a temp directory,
// so a built binary never falls back to types.rs's compile-time repo path.
fn install_adapters(directory: Option<&Path>) -> Result<Option<tempfile::TempDir>> {
    if let Some(directory) = directory {
        std::env::set_var("DL_ADAPTERS_DIR", directory);
        return Ok(None);
    }
    let embedded = tempfile::tempdir().context("temporary directory for the embedded adapters")?;
    let path = embedded.path().join(format!("{PROGRAM_NAME}.adapters.json"));
    std::fs::write(&path, ADAPTERS_JSON)
        .with_context(|| format!("write {}", path.display()))?;
    std::env::set_var("DL_ADAPTERS_DIR", embedded.path());
    Ok(Some(embedded))
}

fn boot() -> Result<GenProgram> {
    Ok(GenProgram::try_from_json(emitted_program::program())?)
}

fn read_schedule(path: &Path) -> Result<Vec<Vec<Arrival>>> {
    let text = std::fs::read_to_string(path)
        .with_context(|| format!("read schedule {}", path.display()))?;
    let batches: Vec<Vec<ArrivalDto>> =
        serde_json::from_str(&text).with_context(|| format!("parse schedule {}", path.display()))?;
    batches
        .into_iter()
        .map(|batch| arrival_batch(batch).map_err(anyhow::Error::from))
        .collect()
}

/// Everything both verbs do before their first tick. The adapters and the
/// schedule are read before `--root` moves the process.
fn prepare(args: &ProgramArgs) -> Result<(GenProgram, Vec<Arrival>, RunOptions, Option<tempfile::TempDir>)> {
    let adapters = install_adapters(args.adapters_dir.as_deref())?;
    let program = boot()?;
    let schedule = match &args.schedule {
        Some(path) => read_schedule(path)?,
        None => Vec::new(),
    };
    let db = match &args.db {
        Some(path) if path.is_relative() => Some(
            std::env::current_dir()
                .context("read the working directory")?
                .join(path),
        ),
        other => other.clone(),
    };
    std::env::set_current_dir(&args.root)
        .with_context(|| format!("move to {}", args.root.display()))?;
    let seeds = run::seed_arrivals(&program, &args.arrive)?;
    Ok((
        program,
        seeds,
        RunOptions {
            schedule,
            live_hosts: !args.no_live_hosts,
            finals: args.finals(),
            db,
            fail_on: args.fail_on.clone(),
            drain_cap: DRAIN_CAP,
        },
        adapters,
    ))
}

fn run(args: ProgramArgs) -> Result<()> {
    let finals = args.finals();
    let (program, seeds, options, _adapters) = prepare(&args)?;
    let outcome = run::run_once(&program, seeds, options)?;
    run::print_outcome(&program, &outcome, &finals)?;
    if outcome.failed() {
        std::process::exit(1);
    }
    Ok(())
}

fn watch(args: ProgramArgs) -> Result<()> {
    let root = args
        .root
        .canonicalize()
        .with_context(|| format!("read {}", args.root.display()))?;
    let (program, seeds, options, _adapters) = prepare(&args)?;
    let (stop, listen) = tokio::sync::watch::channel(false);
    // SIGINT only flips the flag, so the loop finishes the tick it is in.
    std::thread::Builder::new()
        .name("dl6-signal".to_string())
        .spawn(move || {
            let Ok(runtime) = tokio::runtime::Builder::new_current_thread().enable_all().build()
            else {
                return;
            };
            runtime.block_on(async {
                let _ = tokio::signal::ctrl_c().await;
                let _ = stop.send(true);
            });
        })
        .context("spawn the signal thread")?;
    if run::watch(&program, seeds, WatchOptions::new(options, root), listen)? {
        std::process::exit(1);
    }
    Ok(())
}

fn serve(socket: &Path, adapters_dir: Option<&Path>) -> Result<()> {
    let _adapters = install_adapters(adapters_dir)?;
    let program = boot()?;
    let seam = SqliteSeam::in_memory().context("open seam")?;
    let runtime = run::current_thread_runtime()?;
    let empty: Vec<Vec<Arrival>> = Vec::new();
    let folded = runtime
        .block_on(sprefa_engine_rs::driver::run_schedule(
            &program, &seam, &empty, DRAIN_CAP,
        ))?
        .lines
        .len();
    let state = ServeState::resume(program, seam, folded);
    let cancel = CancellationToken::new();
    let socket = socket.to_path_buf();
    runtime.block_on(async move {
        let shutdown = cancel.clone();
        tokio::spawn(async move {
            let _ = tokio::signal::ctrl_c().await;
            shutdown.cancel();
        });
        serve_unix(state, &socket, cancel).await
    })
}

fn main() -> Result<()> {
    match Cli::parse().verb {
        Verb::Run(args) => run(args),
        Verb::Watch(args) => watch(args),
        Verb::Serve {
            socket,
            adapters_dir,
        } => serve(&socket, adapters_dir.as_deref()),
    }
}
